class Solution:
    def sumDistance(self, nums: List[int], s: str, d: int) -> int:
        MOD = 10**9 + 7
        pos = sorted(x + d if c == 'R' else x - d for x, c in zip(nums, s))
        ans = pre = 0
        for i, p in enumerate(pos):
            ans = (ans + i * p - pre) % MOD
            pre += p
        return ans

