class Solution {
public:
    int sumDistance(vector<int>& nums, string s, int d) {
        const long long MOD = 1e9 + 7;
        int n = nums.size();
        vector<long long> pos(n);
        for (int i = 0; i < n; i++)
            pos[i] = (long long)nums[i] + (s[i] == 'R' ? d : -(long long)d);
        sort(pos.begin(), pos.end());
        long long ans = 0, pre = 0;
        for (int i = 0; i < n; i++) {
            ans = (ans + (long long)i % MOD * (pos[i] % MOD) % MOD - pre + MOD * 2) % MOD;
            pre = (pre + pos[i]) % MOD;
        }
        return ans;
    }
};

