class Solution {
    public int sumDistance(int[] nums, String s, int d) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        long[] pos = new long[n];
        for (int i = 0; i < n; i++)
            pos[i] = (long) nums[i] + (s.charAt(i) == 'R' ? d : -(long) d);
        Arrays.sort(pos);
        long ans = 0, pre = 0;
        for (int i = 0; i < n; i++) {
            ans = ((ans + (long) i % MOD * (pos[i] % MOD)) % MOD - pre % MOD + MOD) % MOD;
            pre = (pre + pos[i]) % MOD;
        }
        return (int) ans;
    }
}

