var sumDistance = function(nums, s, d) {
    const MOD = 1e9 + 7;
    const pos = nums.map((x, i) => x + (s[i] === 'R' ? d : -d)).sort((a, b) => a - b);
    let ans = 0, pre = 0;
    for (let i = 0; i < pos.length; i++) {
        ans = (ans + i * pos[i] - pre) % MOD;
        pre = (pre + pos[i]) % MOD;
    }
    return ((ans % MOD) + MOD) % MOD;
};
